solution.solution.cpp:
#include <string>

using Cents = long long;

struct Item
{
    std::string name{};
    Cents price{};
    int quantity{};
};

Cents lineTotal(const Item& item)
{
    return item.price * item.quantity;
}

std::string priceLabel(Cents amount)
{
    const auto dollars{ amount / 100 };
    const auto cents{ amount % 100 };
    std::string label{ "$" + std::to_string(dollars) + "." };
    if (cents < 10)
    {
        label += "0";
    }
    label += std::to_string(cents);
    return label;
}

std::string receiptLine(const Item& item)
{
    return item.name + " x" + std::to_string(item.quantity) + "  " + priceLabel(lineTotal(item));
}

unitTests:
static_assert(std::is_same_v<Cents, long long>);

TEST("lineTotal") { CHECK_EQ(lineTotal(Item{ "Coffee", 250, 3 }), 750); CHECK_EQ(lineTotal(Item{ "Free sample", 0, 10 }), 0); }
TEST("priceLabel") { CHECK_EQ(priceLabel(1205), "$12.05"); CHECK_EQ(priceLabel(300), "$3.00"); CHECK_EQ(priceLabel(7), "$0.07"); CHECK_EQ(priceLabel(99999), "$999.99"); }
TEST("receiptLine") { CHECK_EQ(receiptLine(Item{ "Coffee", 250, 3 }), "Coffee x3  $7.50"); CHECK_EQ(receiptLine(Item{ "Bagel", 105, 1 }), "Bagel x1  $1.05"); }

